import{_ as a,z as l,m as o,ap as e}from"./chunks/framework.40Eg4YuW.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"markdown/FAQ.md","filePath":"markdown/FAQ.md","lastUpdated":1785843060000}'),r={name:"markdown/FAQ.md"};function t(n,i,d,s,h,c){return o(),l("div",null,i[0]||(i[0]=[e('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="安装和配置" tabindex="-1">安装和配置 <a class="header-anchor" href="#安装和配置" aria-label="Permalink to &quot;安装和配置&quot;">​</a></h2><h3 id="q-如何获取-bilibili-uid" tabindex="-1">Q: 如何获取 Bilibili UID？ <a class="header-anchor" href="#q-如何获取-bilibili-uid" aria-label="Permalink to &quot;Q: 如何获取 Bilibili UID？&quot;">​</a></h3><p>A: 有以下几种方法：</p><ol><li><strong>手机端</strong>：进入个人主页 → 查看资料 → 查看UID</li><li><strong>WEB端</strong>：进入个人主页 → 查看地址栏 <code>/</code> 后的数字</li></ol><h3 id="q-扫码登录失败怎么办" tabindex="-1">Q: 扫码登录失败怎么办？ <a class="header-anchor" href="#q-扫码登录失败怎么办" aria-label="Permalink to &quot;Q: 扫码登录失败怎么办？&quot;">​</a></h3><p>A: 请检查：</p><ol><li>确保使用最新版本的 Bilibili APP</li><li>网络连接是否正常</li><li>二维码是否已过期（通常 2 分钟过期）</li><li>确认扫码账号的 UID 与配置项 <code>selfId</code> 完全一致</li><li>尝试重新发起登录或刷新二维码</li></ol><p>扫码成功后，页面会先显示“二维码已扫描，请在手机上确认登录”，此时还需要在手机端完成确认。登录完成后，Cookie 会保存到本地，后续启动会自动验证缓存。</p><h3 id="q-为什么提示-扫码账号和配置项账号不一致-请更换账号" tabindex="-1">Q: 为什么提示“扫码账号和配置项账号不一致，请更换账号”？ <a class="header-anchor" href="#q-为什么提示-扫码账号和配置项账号不一致-请更换账号" aria-label="Permalink to &quot;Q: 为什么提示“扫码账号和配置项账号不一致，请更换账号”？&quot;">​</a></h3><p>A: <code>selfId</code> 用于确定当前插件实例登录哪个账号。适配器会将扫码获得的 Cookie UID 与 <code>selfId</code> 比对，发现不一致时不会把错误账号当作机器人登录，也不会关闭插件。请更换为与配置项 UID 一致的 Bilibili 账号后重新扫码。</p><h3 id="q-插件安装后无法启动" tabindex="-1">Q: 插件安装后无法启动？ <a class="header-anchor" href="#q-插件安装后无法启动" aria-label="Permalink to &quot;Q: 插件安装后无法启动？&quot;">​</a></h3><p>A: 可能的原因：</p><ol><li><strong>依赖问题</strong>：确保 Koishi 版本 &gt;= 4.18.0</li><li><strong>配置错误</strong>：检查 UID 是否正确填写</li><li><strong>网络问题</strong>：确保能正常访问 Bilibili API</li><li><strong>权限问题</strong>：确保 Koishi 有足够的文件读写权限</li></ol><h2 id="使用问题" tabindex="-1">使用问题 <a class="header-anchor" href="#使用问题" aria-label="Permalink to &quot;使用问题&quot;">​</a></h2><h3 id="q-为什么消息发送-接收有延迟" tabindex="-1">Q: 为什么消息发送/接收有延迟？ <a class="header-anchor" href="#q-为什么消息发送-接收有延迟" aria-label="Permalink to &quot;Q: 为什么消息发送/接收有延迟？&quot;">​</a></h3><p>A: 这是正常现象，原因包括：</p><ol><li><strong>B站限制</strong>：为防止滥用，B站对私信 API 有频率限制</li><li><strong>轮询机制</strong>：插件使用轮询方式获取新消息</li><li><strong>网络延迟</strong>：网络环境可能影响响应速度</li></ol><p>私信轮询间隔由 <code>pollInterval</code> 控制，评论通知轮询间隔由 <code>commentPollInterval</code> 控制。默认情况下，私信通常约 3 秒轮询一次，评论通知通常约 30 秒轮询一次。</p><h3 id="q-如何让机器人响应视频或图文动态评论" tabindex="-1">Q: 如何让机器人响应视频或图文动态评论？ <a class="header-anchor" href="#q-如何让机器人响应视频或图文动态评论" aria-label="Permalink to &quot;Q: 如何让机器人响应视频或图文动态评论？&quot;">​</a></h3><p>A: 开启 <code>enableCommentPolling</code>，然后在视频评论区或图文动态评论区 @ 机器人，或回复与机器人相关的评论。适配器会把评论作为标准 Koishi 消息 Session 下发：</p><ul><li>视频评论区频道：<code>video:BV号</code></li><li>图文动态评论区频道：<code>opus:动态ID</code></li></ul><p>评论中的 @ 会转换成 Koishi <code>at</code> 元素，并保留被提及用户的 UID。@ 后面没有空格时也会尝试根据通知中的提及信息识别。Koishi 产生的回复会回复触发通知对应的评论，而不是发送帖子下的一级评论。</p><h3 id="q-头像图片无法显示怎么办" tabindex="-1">Q: 头像图片无法显示怎么办？ <a class="header-anchor" href="#q-头像图片无法显示怎么办" aria-label="Permalink to &quot;Q: 头像图片无法显示怎么办？&quot;">​</a></h3><p>A: 机器人头像会通过 Koishi 本地反代地址提供给控制台，以处理 Bilibili 图片的请求头限制。普通用户头像仍使用 Bilibili 原始 URL。当前版本不再提供 <code>avatarBase64</code> 或 <code>imageToBase64</code> 配置；如果仍看到旧配置，请更新插件或重新加载配置 schema。</p><h3 id="q-消息发送失败" tabindex="-1">Q: 消息发送失败？ <a class="header-anchor" href="#q-消息发送失败" aria-label="Permalink to &quot;Q: 消息发送失败？&quot;">​</a></h3><p>A: 可能的原因：</p><ol><li><strong>内容被屏蔽</strong>：B站有内容审核机制，敏感内容可能被拦截</li><li><strong>频率限制</strong>：发送过于频繁会被限制</li><li><strong>登录过期</strong>：需要重新扫码登录</li><li><strong>网络问题</strong>：检查网络连接</li></ol><h3 id="q-支持发送哪些类型的消息" tabindex="-1">Q: 支持发送哪些类型的消息？ <a class="header-anchor" href="#q-支持发送哪些类型的消息" aria-label="Permalink to &quot;Q: 支持发送哪些类型的消息？&quot;">​</a></h3><p>A: 目前支持：</p><ul><li>✅ 纯文本消息</li><li>✅ 图片消息（需先上传到 B站）</li><li>❌ 视频消息（暂不支持）</li><li>❌ 语音消息（暂不支持）</li><li>❌ 表情包（部分支持）</li></ul><h3 id="q-多个插件实例会互相影响吗" tabindex="-1">Q: 多个插件实例会互相影响吗？ <a class="header-anchor" href="#q-多个插件实例会互相影响吗" aria-label="Permalink to &quot;Q: 多个插件实例会互相影响吗？&quot;">​</a></h3><p>A: 插件支持复用和多配置实例。每个实例根据自己的 <code>selfId</code> 保存 Cookie、维护登录状态和前端服务；多个账号可以同时在线。请为每个实例填写对应账号的 UID，不要在不同实例之间共用同一个账号 Cookie。</p>',33)]))}const b=a(r,[["render",t]]);export{p as __pageData,b as default};
